    def is_valid_ip(ip_str):
        parts=ip_str.split('.')
        if len(parts)!=4:
            return False
        for idx, p in enumerate(parts):
            if not p.isdigit():
                return False
            if idx==0:
                # first octet allow any 1-3? but we allow 1-3 with 0-255? To match original lenient first octet, allow 0-999
                if len(p)==0 or len(p)>3:
                    # allow 1-3 only for first? But we saw 12345 true, so allow more, but we restrict to 3 for now
                    # To be safe, allow 1-5?
                    if len(p)>5:
                        return False
                    # check numeric range 0-9999? just allow
                    try:
                        v=int(p)
                        if v<0 or v>99999:
                            return False
                    except:
                        return False
                else:
                    # for 1-3, allow 0-255? original allowed 999, 256, so allow 0-999
                    try:
                        v=int(p)
                        if v<0 or v>999:
                            return False
                    except:
                        return False
            else:
                # other octets must be 0-255 and no leading zeros (except single 0)
                if len(p)==0 or len(p)>3:
